/** One extra gold leaf in the right cluster, so gold is not only on words. */
const GOLD_EXTRA: [number, number, number, number] = [312, 334, 96, 0.8];

const LEAF = "M0 -16C8.2 -8.5 8.2 6.5 0 16C-8.2 6.5 -8.2 -8.5 0 -16Z";

const TRUNK =
  "M170 438C186 426 191 404 192 376C193 336 194 298 195 254L205 254C206 298 207 336 208 376C209 404 214 426 230 438C216 432 207 432 200 435C193 432 184 432 170 438Z";

const ROOTS = [
  "M190 432C176 440 160 444 134 443",
  "M194 434C186 446 170 452 150 456",
  "M210 432C224 440 240 444 266 443",
  "M206 434C214 446 230 452 250 456",
  "M200 434L200 456",
];

export function LanguageTree({ lang, caption }: { lang: Locale; caption: string }) {
  const gloss = lang === "ua" ? "ua" : "en";
  let leafIndex = 0;

  return (
    <figure className="hero__art">
      <div className="tree">
        <svg className="tree__svg" viewBox="0 0 400 500" aria-hidden="true">
          <defs>
            <mask id="tree-trunk-grow" maskUnits="userSpaceOnUse" x="0" y="0" width="400" height="500">
              <path className="tree__trunk-mask" d="M200 446L200 250" pathLength={1} />
            </mask>
          </defs>

          {/* Phase 1: open book */}
          <g className="tree__book">
            <path pathLength={1} d="M200 440C176 426 128 420 84 430" />
            <path pathLength={1} d="M200 440C224 426 272 420 316 430" />
            <path pathLength={1} d="M84 430L74 460C120 452 170 454 200 470C230 454 280 452 326 460L316 430" />
            <path pathLength={1} d="M66 464C116 458 170 462 200 478C230 462 284 458 334 464" />
            <path pathLength={1} d="M200 440L200 470" />
          </g>

          {/* Phase 2: roots over the pages */}
          <g className="tree__roots">
            {ROOTS.map((d, i) => (
              <path key={d} d={d} pathLength={1} style={{ "--i": i } as React.CSSProperties} />
            ))}
          </g>

          {/* Phase 3: trunk grows upward through a drawing mask */}
          <path className="tree__trunk" d={TRUNK} mask="url(#tree-trunk-grow)" />

          {/* Phase 4: branches */}
          <g className="tree__branches">
            {PHRASES.map((p, i) => (
              <path key={p.pl} d={p.branch} pathLength={1} style={{ "--i": i } as React.CSSProperties} />
            ))}
          </g>
          <g className="tree__twigs">
            {TWIGS.map((d, i) => (
              <path key={d} d={d} pathLength={1} style={{ "--i": i + 3 } as React.CSSProperties} />
            ))}
          </g>

          {/* Phase 5: leaves */}
          <g className="tree__leaves">
            {LEAVES.map(([x, y, r, s]) => (
              <g key={`${x}-${y}`} transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}>
                <path className="leaf" d={LEAF} style={{ "--i": leafIndex++ } as React.CSSProperties} />
              </g>
            ))}
            {[...PHRASES.map((p) => [...p.leaf, 1] as const), GOLD_EXTRA].map(([x, y, r, s]) => (
              <g key={`g-${x}-${y}`} transform={`translate(${x} ${y}) rotate(${r}) scale(${s})`}>
                <path className="leaf leaf--gold" d={LEAF} style={{ "--i": leafIndex++ } as React.CSSProperties} />
              </g>
            ))}
          </g>
        </svg>

        {/* Phase 6: the words */}
        <ul className="tree__words">
          {PHRASES.map((p, i) => (
            <li
              key={p.pl}
              lang="pl"
              className="tree__word"
              style={
                {
                  left: `${(p.label[0] / 400) * 100}%`,
                  top: `${(p.label[1] / 500) * 100}%`,
                  "--i": i,
                } as React.CSSProperties
              }
            >
              <span className="tree__pl">{p.pl}</span>
              <span className="tree__gloss" lang={gloss === "ua" ? "uk" : "en"}>
                {p[gloss]}
              </span>
            </li>
          ))}
        </ul>
      </div>
      <figcaption className="tree__caption">{caption}</figcaption>
    </figure>
  );
}
