import { getDictionary, type Locale } from "@/lib/i18n";
import { site } from "@/lib/site";
import { CtaButton } from "./EnquiryProvider";
import { GoogleG, Stars } from "./Icons";
import { LanguageTree } from "./LanguageTree";

export function Hero({ lang }: { lang: Locale }) {
  const t = getDictionary(lang);

  return (
    <section className="hero" aria-labelledby="hero-title">
      <div className="container hero__grid">
        <div className="hero__copy">
          <p className="hero__kicker hero-in" style={{ "--i": 0 } as React.CSSProperties}>
            {t.hero.kicker}
          </p>
          <h1 id="hero-title" className="hero__title">
            {t.hero.title.map((line, i) => (
              <span className="line-mask" key={i}>
                <span className="hero-line" style={{ "--i": i } as React.CSSProperties}>
                  {line}
                </span>
              </span>
            ))}
          </h1>
          <p className="hero__lead hero-in" style={{ "--i": 3 } as React.CSSProperties}>
            {t.hero.lead}
          </p>
          <div className="hero__actions hero-in" style={{ "--i": 4 } as React.CSSProperties}>
            <CtaButton size="lg">{t.hero.cta}</CtaButton>
            <a href="#jak-uczymy" className="btn btn--ghost btn--lg">
              {t.hero.secondary}
            </a>
          </div>
          <a
            className="rating hero-in"
            style={{ "--i": 5 } as React.CSSProperties}
            href={site.google.mapsUrl}
            target="_blank"
            rel="noopener"
            aria-label={`${t.formatRating(site.google.rating)} / 5 ${t.hero.ratingSuffix}, ${t.reviewsCount(site.google.reviewCount)}. ${t.hero.reviewsLink}`}
          >
            <GoogleG size={26} className="rating__g" />
            <span className="rating__body">
              <span className="rating__top">
                <Stars size={16} />
                <strong>{t.formatRating(site.google.rating)} / 5</strong>
                <span>{t.hero.ratingSuffix}</span>
              </span>
              <span className="rating__link">
                {t.reviewsCount(site.google.reviewCount)} · {t.hero.reviewsLink}
              </span>
            </span>
          </a>
        </div>

        <LanguageTree lang={lang} caption={t.hero.treeCaption} />
      </div>
    </section>
  );
}
